function countPrefix(words, prefix) {
  const root = { next: {}, count: 0 } //@init
  let node = root
  for (const word of words) {
    node = root //@word
    for (const ch of word) {
      node = node.next[ch] ??= { next: {}, count: 0, end: false } //@insert
      node.count++ //@count
    }
    node.end = true //@end
  }
  node = root //@lookup
  for (const ch of prefix) {
    if (!(ch in node.next)) return 0 //@check
    node = node.next[ch] //@step
  }
  return node.count //@done
}

