class Trie {
  constructor() {
    this.root = { next: new Map(), count: 0, end: false }
  }

  insert(word) {
    let node = this.root
    for (const ch of word) {
      if (!node.next.has(ch)) node.next.set(ch, { next: new Map(), count: 0, end: false })
      node = node.next.get(ch)
      node.count++ // words passing through this prefix
    }
    node.end = true // a whole word stops here
  }

  find(prefix) {
    let node = this.root
    for (const ch of prefix) {
      node = node.next.get(ch)
      if (!node) return null // no word starts with prefix
    }
    return node
  }
}

template.ts:
type TrieNode = { next: Map<string, TrieNode>; count: number; end: boolean }

class Trie {
  root: TrieNode = { next: new Map(), count: 0, end: false }

  insert(word: string): void {
    let node = this.root
    for (const ch of word) {
      let child = node.next.get(ch)
      if (!child) node.next.set(ch, child = { next: new Map(), count: 0, end: false })
      node = child
      node.count++ // words passing through this prefix
    }
    node.end = true // a whole word stops here
  }

  find(prefix: string): TrieNode | null {
    let node: TrieNode | undefined = this.root
    for (const ch of prefix) {
      node = node.next.get(ch)
      if (!node) return null // no word starts with prefix
    }
    return node
  }
}

