  for (const root of roots) {
    let node = trie
    for (const ch of root) node = node[ch] ??= {}
    node.$ = true
  }
  return sentence.split(' ').map(word => {
    let node = trie
    let cut = word
    for (let i = 0; i < word.length; i++) {
      node = node[word[i]]
      if (!node) break
      if (node.$) cut = word.slice(0, i + 1)
    }
    return cut
  }).join(' ')
