def replace_with_roots(roots, sentence):
    trie = {}
    for root in roots:
        node = trie
        for ch in root:
            node = node.setdefault(ch, {})
        node['$'] = True
    out = []
    for word in sentence.split():
        node, cut = trie, word
        for i, ch in enumerate(word):
            if ch not in node:
                break
            node = node[ch]
            if '$' in node:
                cut = word[:i + 1]
        out.append(cut)
    return ' '.join(out)

